#!/usr/bin/env bash
# Cria a logo da Microsoft (ms-logo.png) no servidor e reconstroi a plataforma.
# Rode DENTRO da pasta gophish-platform, no servidor (172.16.154.58).
set -e
mkdir -p backend/app/static/brand
printf '%s' '' | base64 -d > backend/app/static/brand/ms-logo.png
echo "ms-logo.png: $(wc -c < backend/app/static/brand/ms-logo.png) bytes"
docker compose up -d --build
echo "OK. Teste: curl -I http://172.16.154.58:8000/static/brand/ms-logo.png"
